join public.directory_listings d on d.slug = c.slug
where not exists (
  select 1 from public.crm_orgs o
  where o.directory_listing_id = d.id
     or (lower(o.name) = lower(c.name) and coalesce(o.district,'') = coalesce(c.district,''))
);

-- ── report ───────────────────────────────────────────────────────────────────
select category_group, count(*) from public.directory_listings
where subtype in ('agency','property-management','car-rental','movers','banking','insurance','law-firm','accounting')
group by category_group order by 2 desc;
